import { useEffect, useState } from 'react'

interface WeatherData {
  temp: number
  condition: string
  city: string
}

export function DotoClock() {
  const [time, setTime] = useState<string>('')
  const [weather, setWeather] = useState<WeatherData | null>(null)
  const [loading, setLoading] = useState(true)

  // Fetch weather on mount
  useEffect(() => {
    const fetchWeather = async () => {
      try {
        const response = await fetch('https://api.open-meteo.com/v1/forecast?latitude=40.7128&longitude=-74.0060&current=temperature_2m,weather_code&temperature_unit=fahrenheit')
        const data = await response.json()
        const current = data.current
        const weatherConditions: { [key: number]: string } = {
          0: 'Clear',
          1: 'Cloudy',
          2: 'Cloudy',
          3: 'Overcast',
          45: 'Foggy',
          48: 'Foggy',
          51: 'Rain',
          53: 'Rain',
          55: 'Rain',
          61: 'Rain',
          63: 'Rain',
          65: 'Rain',
          71: 'Snow',
          73: 'Snow',
          75: 'Snow',
          80: 'Showers',
          81: 'Showers',
          82: 'Showers',
          85: 'Snow Showers',
          86: 'Snow Showers',
          95: 'Thunderstorm',
          96: 'Thunderstorm',
          99: 'Thunderstorm',
        }
        setWeather({
          temp: Math.round(current.temperature_2m),
          condition: weatherConditions[current.weather_code] || 'Unknown',
          city: 'New York',
        })
      } catch (err) {
        console.error('Weather fetch error:', err)
        setWeather({
          temp: 72,
          condition: 'N/A',
          city: 'N/A',
        })
      } finally {
        setLoading(false)
      }
    }

    fetchWeather()
    const weatherInterval = setInterval(fetchWeather, 600000) // Update every 10 minutes

    return () => clearInterval(weatherInterval)
  }, [])

  useEffect(() => {
    const updateTime = () => {
      const now = new Date()
      const hours = String(now.getHours()).padStart(2, '0')
      const minutes = String(now.getMinutes()).padStart(2, '0')
      const seconds = String(now.getSeconds()).padStart(2, '0')
      setTime(`${hours}:${minutes}:${seconds}`)
    }

    updateTime()
    const interval = setInterval(updateTime, 1000)

    return () => clearInterval(interval)
  }, [])

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        display: 'flex',
        alignItems: 'center',
        minHeight: '240px',
        minHeight: '200px',
        background: 'linear-gradient(135deg, #1a1a1a 0%, #0f0f0f 100%)',
        borderRadius: '12px',
        gap: '24px',
        fontVariationSettings: '"ROND" 0',
      }}
      {/* Time Display */}
      <div
        style={{
          fontFamily: '"Doto", sans-serif',
          fontOpticalSizing: 'auto',
          fontWeight: 700,
          fontSize: '96px',
          letterSpacing: '0.1em',
          color: '#ffffff',
          textShadow: '0 0 20px rgba(255, 255, 255, 0.3)',
          fontVariationSettings: '"ROND" 0',
        }}
      >
        {time || '00:00:00'}
      </div>

      {/* Weather Display */}
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '16px',
          fontFamily: '"Doto", sans-serif',
          color: '#b3b3b3',
          fontSize: '24px',
          fontWeight: 500,
        }}
      >
        {loading ? (
          <span>Loading weather...</span>
        ) : weather ? (
          <>
            <span>{weather.city}</span>
            <span>•</span>
            <span>{weather.temp}°F</span>
            <span>•</span>
            <span>{weather.condition}</span>
          </>
        ) : (
          <span>Weather unavailable</span>
        )}
      </div>
      {time || '00:00:00'}
    </div>
  )
}
